out = [row[:] for row in G]
H, W = len(G), len(G[0])
def is_marked(i, j): return 0 <= i < H and 0 <= j < W and G[i][j] == 8
dots = [(i,j) for i in range(H) for j in range(W)
        if G[i][j] == 8 and not any(is_marked(i+di, j+dj) for di,dj in [(1,0),(-1,0),(0,1),(0,-1)])]
print(dots)
for i, j in dots:
    for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
        x, y = i+di, j+dj
        while 0 <= x < H and 0 <= y < W and G[x][y] != 8:
            out[x][y] = 2
            x += di; y += dj
        # paint only if ray terminated at a marked cell (border/dot)
        if not (0 <= x < H and 0 <= y < W):
            # ran off grid without hitting marked: undo
            x -= di; y -= dj
            while (x, y) != (i, j) and G[x][y] != 8:
                out[x][y] = 3
                x -= di; y -= dj
for row in out: print(' '.join(map(str, row)))

